def T(liuyao, cm=False, ru=False, di=False, reason=""):
    if not liuyao:
        return {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}

